import{_ as r,o,c as n,a2 as s}from"./chunks/framework.Dkj3JE0_.js";const p=JSON.parse('{"title":"日本語文法の基礎","description":"","frontmatter":{"title":"日本語文法の基礎"},"headers":[],"relativePath":"jp/blogs/JLPT-N2/grammars.md","filePath":"jp/blogs/JLPT-N2/grammars.md"}'),l={name:"jp/blogs/JLPT-N2/grammars.md"};function g(i,t,a,e,d,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="日本語文法の基礎" tabindex="-1">日本語文法の基礎 <a class="header-anchor" href="#日本語文法の基礎" aria-label="Permalink to &quot;日本語文法の基礎&quot;">​</a></h1><p>N2 の文法を学ぶ前に確認しておきたい基本の文型です。以下では <strong>N</strong> を名詞、<strong>A/B</strong> を文中の各位置に入る語句として使います。</p><h2 id="a-は-b-です" tabindex="-1">A は B です <a class="header-anchor" href="#a-は-b-です" aria-label="Permalink to &quot;A は B です&quot;">​</a></h2><p><strong>規則：</strong> は は「わ」と読み、話題を示します。「A について言えば」という意味です。名詞やナ形容詞を述語にする文では、です を付けると丁寧になります。話題は必ずしも文法上の主語と同じではありません。</p><ul><li>私は留学生です。——話し手が留学生であることを述べています。</li><li>あの方は先生です。——あの人が先生であることを丁寧に述べています。</li></ul><p><strong>否定：</strong> A は B ではありません。会話では B じゃありません とも言います。</p><ul><li>私は先生ではありません。——先生であることを否定しています。</li></ul><p><strong>疑問：</strong> 丁寧な文の末尾に か を付けます。書くときの疑問符は必須ではありません。</p><ul><li>あの方は先生ですか。——あの方の職業を尋ねています。</li></ul><p><strong>述語をつなぐ：</strong> 名詞やナ形容詞の述語を次の述語につなぐときは B で を使います。この で は断定の助動詞の連用形であり、動作の場所を示す助詞ではありません。</p><ul><li>田中さんは先生で、作家です。——田中さんには二つの職業があります。</li></ul><h2 id="指示語" tabindex="-1">指示語 <a class="header-anchor" href="#指示語" aria-label="Permalink to &quot;指示語&quot;">​</a></h2><p><strong>規則：</strong> 語頭の <strong>こ</strong> は話し手の近く、<strong>そ</strong> は聞き手の近くや前に話題に出たもの、<strong>あ</strong> は両者から離れたもの、<strong>ど</strong> は疑問を表します。会話では、そ・あ が共通の記憶にあるものを指すこともあります。距離は基本的な目安です。</p><table tabindex="0"><thead><tr><th>位置</th><th>物</th><th>場所</th><th>方向／人を丁寧に指す語</th></tr></thead><tbody><tr><td>話し手の近く</td><td>これ</td><td>ここ</td><td>こちら</td></tr><tr><td>聞き手の近く</td><td>それ</td><td>そこ</td><td>そちら</td></tr><tr><td>両者から遠い</td><td>あれ</td><td>あそこ</td><td>あちら</td></tr><tr><td>疑問</td><td>どれ</td><td>どこ</td><td>どちら</td></tr></tbody></table><ul><li>これは私の本です。——話し手の近くにある本を指しています。</li><li>駅はどちらですか。——駅の方向を丁寧に尋ねています。</li></ul><p>こちら／そちら／あちら／どちら は、文脈によって人や選択肢を丁寧に指す場合もあります。</p><h2 id="n1-に-n2-が-あります-います" tabindex="-1">N1 に N2 が あります／います <a class="header-anchor" href="#n1-に-n2-が-あります-います" aria-label="Permalink to &quot;N1 に N2 が あります／います&quot;">​</a></h2><p><strong>規則：</strong> N1 という場所に N2 が存在することを初めて伝える形です。に は場所、が は存在するものを示します。物や植物には <strong>あります</strong>、人や動物には <strong>います</strong> を使います。</p><ul><li>机の上に本があります。——机の上に本があることを伝えています。</li><li>教室に学生がいます。——教室に学生がいることを伝えています。</li></ul><p>所有を表す場合は、人を存在の基準にすることもできます：私には兄がいます。——自分に兄がいるという意味です。</p><h2 id="n1-には-n2-が-あります-います" tabindex="-1">N1 には N2 が あります／います <a class="header-anchor" href="#n1-には-n2-が-あります-います" aria-label="Permalink to &quot;N1 には N2 が あります／います&quot;">​</a></h2><p><strong>規則：</strong> には は場所を示す に と、話題・対比を示す は の組み合わせです。N1 を話題の範囲として示し、別の場所や人との対比を含むことがあります。N2 に合わせて あります／います を選びます。</p><ul><li>この町には大きな公園があります。——この町について、公園があると述べています。</li><li>私のクラスには留学生がいます。——自分のクラスについて、留学生がいると述べています。</li></ul><p><strong>教室に学生がいます</strong> は学生の存在を伝え、<strong>教室には学生がいます</strong> は「教室には」と場所をより強く話題にします。</p><h2 id="n1-は-n2-に-あります-います" tabindex="-1">N1 は N2 に あります／います <a class="header-anchor" href="#n1-は-n2-に-あります-います" aria-label="Permalink to &quot;N1 は N2 に あります／います&quot;">​</a></h2><p><strong>規則：</strong> すでに分かっている N1 が<strong>どこにある／いるか</strong>を述べる形です。は は既知の話題、に は場所を示します。N1 に合わせて あります／います を選びます。</p><ul><li>本は机の上にあります。——その本の場所を伝えています。</li><li>先生は職員室にいます。——先生の居場所を伝えています。</li></ul><p><strong>机の上に本があります</strong> は本の存在を新しく伝え、<strong>本は机の上にあります</strong> は既知の本の場所を伝えます。</p><h2 id="過去形-名詞述語" tabindex="-1">過去形：名詞述語 <a class="header-anchor" href="#過去形-名詞述語" aria-label="Permalink to &quot;過去形：名詞述語&quot;">​</a></h2><p><strong>規則：</strong> 丁寧体の名詞文では です を <strong>でした</strong> に変えます。否定の過去形は <strong>ではありませんでした</strong> で、会話では <strong>じゃありませんでした</strong> とも言います。ナ形容詞の述語にも同じ形を使います。</p><table tabindex="0"><thead><tr><th>意味</th><th>文型</th><th>例文</th></tr></thead><tbody><tr><td>過去の肯定</td><td>A は B でした</td><td>昨日は休みでした。——昨日が休みだったことを述べています。</td></tr><tr><td>過去の否定</td><td>A は B ではありませんでした</td><td>昨日は休みではありませんでした。——昨日が休みではなかったことを述べています。</td></tr></tbody></table><p>普通体では <strong>だった</strong>、<strong>ではなかった</strong>（または <strong>じゃなかった</strong>）を使います：昨日は休みだった。</p><h2 id="過去形-動詞述語" tabindex="-1">過去形：動詞述語 <a class="header-anchor" href="#過去形-動詞述語" aria-label="Permalink to &quot;過去形：動詞述語&quot;">​</a></h2><p><strong>規則：</strong> 丁寧体では、肯定の <strong>～ます</strong> を <strong>～ました</strong> に、否定の <strong>～ません</strong> を <strong>～ませんでした</strong> に変えます。普通体の過去形は動詞の種類によって変わるため、ます を単純に た に置き換えることはできません。</p><table tabindex="0"><thead><tr><th>意味</th><th>丁寧体</th><th>普通体</th></tr></thead><tbody><tr><td>過去の肯定</td><td>昨日、映画を見ました。——昨日見たことを述べています。</td><td>昨日、映画を見た。</td></tr><tr><td>過去の否定</td><td>昨日、映画を見ませんでした。——昨日見なかったことを述べています。</td><td>昨日、映画を見なかった。</td></tr></tbody></table><p>例えば、行きます → 行きました → 行った、食べます → 食べました → 食べた です。</p><h2 id="疑問詞と-が" tabindex="-1">疑問詞と が <a class="header-anchor" href="#疑問詞と-が" aria-label="Permalink to &quot;疑問詞と が&quot;">​</a></h2><p><strong>規則：</strong> 「誰が／何が」主語なのかを尋ねるとき、疑問詞には が を付けます。答えでも が を使って主語を特定することが一般的です。ただし、すでに分かっている話題として述べたり対比したりする場合は は も使えます。「が で尋ねたら必ず が で答える」という決まりではありません。</p><ul><li>誰が来ましたか。——来た人を尋ねています。</li><li>田中さんが来ました。——来た人を特定しています。</li><li>何がありますか。——存在するものを尋ねています。</li><li>机の上に本があります。——本があると答えています。</li></ul><h2 id="この-その-あの-どの" tabindex="-1">この／その／あの／どの <a class="header-anchor" href="#この-その-あの-どの" aria-label="Permalink to &quot;この／その／あの／どの&quot;">​</a></h2><p><strong>規則：</strong> これらは名詞を直接修飾する <strong>連体詞</strong> で、後ろに名詞が必要です。この本、その本、あの本、どの本 のように使います。名詞を付けずに物を指すときは、これ／それ／あれ／どれ を使います。</p><ul><li>この本は面白いです。——近くの本について述べています。</li><li>これは面白いです。——名詞を繰り返さず、近くのものを指しています。</li><li>どの本があなたのですか。——本の中から一冊を尋ねています。</li><li>どれがあなたのですか。——名詞を繰り返さずに尋ねています。</li></ul><h2 id="n-を-n-をください" tabindex="-1">N を / N をください <a class="header-anchor" href="#n-を-n-をください" aria-label="Permalink to &quot;N を / N をください&quot;">​</a></h2><p><strong>規則：</strong> 助詞 <strong>を</strong> は名詞の後に付いて<strong>直接目的語</strong>を示します。日本語は SOV 型の言語なので、動詞はふつう文末に来ます。目的語はその前に置かれ、を で示します。</p><p><strong>N をください：</strong> ください は くださる（くれる の尊敬語）の命令形です。<strong>N をください</strong> は「……を私にください」という意味で、買い物や注文のときによく使います。</p><ul><li>水族館の入場券をください。</li><li>チーズバーガーセットをください。</li><li>ビールをください。</li></ul><p><strong>も：</strong> 「……も」と言うときは <strong>も</strong> を使います。も と を は重ねず、も が を に<strong>取って代わります</strong>。</p><ul><li>それから、ホットコーヒーもください。</li></ul><h2 id="n-を-数量-ください" tabindex="-1">N を（数量）ください <a class="header-anchor" href="#n-を-数量-ください" aria-label="Permalink to &quot;N を（数量）ください&quot;">​</a></h2><p><strong>規則：</strong> 欲しい数を言うときは、<strong>数量詞</strong>を ください の前に置きます：<strong>N を［数量詞］ください</strong>。日本語では数量詞はふつう動詞の前に来ます。</p><ul><li>この水族館の入場券を3枚ください。／はい、3000円です。</li><li>チーズバーガーセットを一つください。</li><li>あのう、これを2本ください。</li><li>シャツを3枚ください。</li></ul><p>数量詞はほかの動詞の前にも来ます：兄が2人います。／スマホが2台あります。</p><p>ここで使った助数詞：<strong>枚</strong>（平たいもの）、<strong>一つ</strong>（一般のもの）、<strong>本</strong>（細長いもの）、<strong>人</strong>（人）、<strong>台</strong>（機械）。</p><h2 id="n-をお願いします-n-でお願いします" tabindex="-1">N をお願いします / N でお願いします <a class="header-anchor" href="#n-をお願いします-n-でお願いします" aria-label="Permalink to &quot;N をお願いします / N でお願いします&quot;">​</a></h2><p><strong>規則：</strong> <strong>お願いします</strong> は丁寧な依頼の表現です。注文の場面では多くの場合 <strong>ください</strong> の代わりに使えます。</p><ul><li>ホットコーヒーをお願いします。</li><li>これを４つお願いします。</li></ul><p><strong>N でお願いします：</strong> 助詞 <strong>で</strong> は<strong>手段・方法・選んだ選択肢</strong>を示します。サイズ、支払い方法、連絡手段などを指定するときに使います。とくに、品物そのものが文脈ですでに明らかなときに自然です。</p><ul><li>Sサイズでお願いします。——店員がすでにサイズを尋ねた後なら自然。</li><li>Sサイズのコーヒーをお願いします。——品物の名前も言っている。</li><li>アリペイでお願いします。——支払いのとき。</li><li>Eメールでお願いします。——連絡方法を聞かれたとき。</li></ul><h2 id="n-でございます" tabindex="-1">N でございます <a class="header-anchor" href="#n-でございます" aria-label="Permalink to &quot;N でございます&quot;">​</a></h2><p><strong>規則：</strong> <strong>でございます</strong> は <strong>です</strong> よりさらに丁寧で改まった言い方（丁寧語）です。接客、スピーチなどの改まった場面でよく使います。ふつうは話し手自身、話し手の身内、またはそれに属するものについて使い、敬うべき聞き手や聞き手のものには通常使いません。</p><ul><li>エレベーターはこちらでございます。</li><li>私が担当者でございます。</li><li>部長の田中でございます。<em>（同僚が取引先に自社の部長を紹介する場面）</em></li></ul><p>会話：</p><ul><li>A <em>（社外の人）</em>：田中部長は、今日、お休みですか。</li><li>B <em>（同僚）</em>：はい、休みでございます。</li></ul><h2 id="どうなさいますか-はどうですか" tabindex="-1">どうなさいますか / ～はどうですか <a class="header-anchor" href="#どうなさいますか-はどうですか" aria-label="Permalink to &quot;どうなさいますか / ～はどうですか&quot;">​</a></h2><p><strong>規則：</strong> <strong>どう</strong> は「どのように／（選択として）何を」という意味です。<strong>なさいます</strong> は <strong>する</strong> の尊敬語なので、<strong>どうなさいますか</strong> は「いかがなさいますか」に近い、とても丁寧な問いかけで、接客でよく使います。</p><ul><li>A：ホットコーヒーのサイズはどうなさいますか。</li><li>B：Lサイズでお願いします。</li></ul><p><strong>～はどうですか：</strong> <strong>どう</strong> が <strong>ですか</strong> と一緒に述語になると、<strong>～はどうですか</strong> は意見や様子を尋ねる表現になります。</p><ul><li>このコーヒーはどうですか。</li><li>清華大学はどうですか。</li><li>最近はどうですか。</li></ul><h2 id="形容詞述語-丁寧・非過去" tabindex="-1">形容詞述語（丁寧・非過去） <a class="header-anchor" href="#形容詞述語-丁寧・非過去" aria-label="Permalink to &quot;形容詞述語（丁寧・非過去）&quot;">​</a></h2><p><strong>規則：</strong> 形容詞の述語は<strong>状態</strong>や<strong>変わらない性質</strong>を表します。日本語の形容詞には 2 種類あります：<strong>I 類</strong>（イ形容詞、<strong>い</strong> で終わる）と <strong>II 類</strong>（ナ形容詞／形容動詞）。</p><p><strong>丁寧・非過去（敬体）：</strong></p><ol><li><strong>肯定：</strong> I 類 → <strong>A₁ + です</strong>；II 類 → <strong>A₂ + です</strong>。</li><li><strong>否定：</strong> I 類 → <strong>い</strong> を取って <strong>く + ありません</strong>；II 類 → <strong>A₂ + ではありません</strong>（話し言葉：<strong>じゃありません</strong>）。</li></ol><table tabindex="0"><thead><tr><th>種類</th><th>時制</th><th>肯定（丁寧）</th><th>否定（丁寧）</th></tr></thead><tbody><tr><td>I 類（例：高い）</td><td>非過去</td><td>高いです</td><td>高くありません</td></tr><tr><td>II 類（例：静か）</td><td>非過去</td><td>静かです</td><td>静かではありません（じゃありません）</td></tr></tbody></table><p>話し言葉では <strong>では</strong> を <strong>じゃ</strong> に替えられます。</p><ul><li>東京は寒いです。</li><li>あの映画は面白くありません。</li><li>先生は親切です。</li><li>日本語は簡単ではありません。</li></ul><p><strong>いい：</strong> 古い形 <strong>よい</strong> から活用します。いいです の否定は <strong>よくありません</strong>。</p><ul><li>成績はよくありません。</li></ul><h2 id="n1-は-n2-が-〜" tabindex="-1">N₁ は N₂ が 〜 <a class="header-anchor" href="#n1-は-n2-が-〜" aria-label="Permalink to &quot;N₁ は N₂ が 〜&quot;">​</a></h2><p><strong>規則：</strong> <strong>は</strong> は<strong>話題</strong>（文が何について述べているか）を、<strong>が</strong> は後に続く述語の<strong>主語</strong>を示します。<strong>A は B が X です</strong> では、A はふつう人や全体、B は A の一部分や一側面で、<strong>B が X です</strong> が A の性質を表します。この「話題 + 部分・側面」の文型は日本語ではよく使われ、中国語や英語の言い方とは異なることが多いです。</p><ul><li>象は鼻が長いです。</li><li>富士山は形がいいです。</li><li>今日は天気がいいです。</li><li>彼女は性格が明るいです。</li></ul><h2 id="あまり-そんなに-形容詞-否定" tabindex="-1">あまり / そんなに + 形容詞（否定） <a class="header-anchor" href="#あまり-そんなに-形容詞-否定" aria-label="Permalink to &quot;あまり / そんなに + 形容詞（否定）&quot;">​</a></h2><p><strong>規則：</strong> 程度を表す副詞 <strong>あまり</strong> と <strong>そんなに</strong> は、形容詞の<strong>否定</strong>形と一緒に使って「それほど……ない」という意味になります。I 類・II 類の形容詞の丁寧な否定形（寒くありません、難しくありません など）と一緒に使います。</p><ul><li>A：東京は寒いですか。</li><li>B：いいえ、あまり寒くありません。</li><li>日本語はそんなに難しくありません。</li><li>このパソコンはそんなに遅くありません。</li></ul><h2 id="〜から-理由" tabindex="-1">〜から（理由） <a class="header-anchor" href="#〜から-理由" aria-label="Permalink to &quot;〜から（理由）&quot;">​</a></h2><p><strong>規則：</strong> 節や文の終わりに付く <strong>から</strong> は<strong>理由・原因</strong>を表します。単独で答えとして使うことも、先に結論を述べた文の後に付け加えることもできます。</p><ul><li>（中村さんは）とても真面目ですから。</li><li>アイスクリームがいいです。暑いですから。</li><li>A：寒いですね。</li><li>B：そうですね。今日は雪ですから。</li></ul><h2 id="n-はどうですか-性質・意見を尋ねる" tabindex="-1">N はどうですか（性質・意見を尋ねる） <a class="header-anchor" href="#n-はどうですか-性質・意見を尋ねる" aria-label="Permalink to &quot;N はどうですか（性質・意見を尋ねる）&quot;">​</a></h2><p><strong>規則：</strong> <strong>どう</strong> は「どのような」という意味です。<strong>N はどうですか</strong> は、あるものの<strong>性質</strong>や、それについての聞き手の<strong>意見</strong>を尋ねます。形容詞の述語（または短い評価の言葉）で答えます。</p><ul><li>A：日本の留学生生活はどうですか。</li><li>B：順調ですよ。</li><li>A：日本語はどうですか。</li><li>B：難しいです。</li><li>A：この映画はどうですか。</li><li>B：とても面白いです。</li></ul><h2 id="〜よ-主張・強調" tabindex="-1">〜よ（主張・強調） <a class="header-anchor" href="#〜よ-主張・強調" aria-label="Permalink to &quot;〜よ（主張・強調）&quot;">​</a></h2><p><strong>規則：</strong> 文末の <strong>よ</strong> は、話し手の<strong>主張</strong>、強い言い切り、強調の気持ちを表します。聞き手にとって新しい情報や、念を押したいことを伝えるときによく使います。</p><ul><li>中村さんのおかげですよ。</li><li>山羊座の人はみんな真面目ですよ。</li><li>日本語はそんなに難しくありませんよ。</li></ul><h2 id="〜ね-軽い感嘆" tabindex="-1">〜ね（軽い感嘆） <a class="header-anchor" href="#〜ね-軽い感嘆" aria-label="Permalink to &quot;〜ね（軽い感嘆）&quot;">​</a></h2><p><strong>規則：</strong> 文末の <strong>ね</strong> は<strong>軽い感嘆・共感</strong>を表すことがあります。<strong>下降調</strong>（↘）で読みます。より柔らかくしたいときは <strong>ねえ</strong> と伸ばします。</p><ul><li>由加ちゃんはすごいですね。↘</li><li>この洋服、かわいいですね。↘</li><li>由加ちゃんのこのスマホケース、かわいいですね。↘</li></ul><h2 id="形容詞述語-丁寧・過去" tabindex="-1">形容詞述語（丁寧・過去） <a class="header-anchor" href="#形容詞述語-丁寧・過去" aria-label="Permalink to &quot;形容詞述語（丁寧・過去）&quot;">​</a></h2><p><strong>規則：</strong> 形容詞述語の過去形は種類によって異なります。</p><ol><li><strong>過去・肯定：</strong> I 類 → <strong>い</strong> を取って <strong>かったです</strong>；II 類 → <strong>A₂ + でした</strong>。</li><li><strong>過去・否定：</strong> I 類 → <strong>い</strong> を取って <strong>く + ありませんでした</strong>；II 類 → <strong>A₂ + ではありませんでした</strong>（話し言葉：<strong>じゃありませんでした</strong>）。</li></ol><table tabindex="0"><thead><tr><th>種類</th><th>時制</th><th>肯定（丁寧）</th><th>否定（丁寧）</th></tr></thead><tbody><tr><td>I 類（例：高い）</td><td>非過去</td><td>高いです</td><td>高くありません</td></tr><tr><td></td><td>過去</td><td>高かったです</td><td>高くありませんでした</td></tr><tr><td>II 類（例：静か）</td><td>非過去</td><td>静かです</td><td>静かではありません（じゃありません）</td></tr><tr><td></td><td>過去</td><td>静かでした</td><td>静かではありませんでした（じゃありませんでした）</td></tr></tbody></table><p>話し言葉では <strong>では</strong> を <strong>じゃ</strong> に替えられます。</p><ul><li>A：お客さんは多かったですか。</li><li>B：ううん、平日の昼間ですから、ばらばらでしたよ。</li><li>子供の時、生活は豊かではありませんでした。</li><li>10年前の家賃はそんなに高くありませんでした。</li></ul><h2 id="ない-否定-形容詞・名詞の四象限" tabindex="-1">ない（否定）／形容詞・名詞の四象限 <a class="header-anchor" href="#ない-否定-形容詞・名詞の四象限" aria-label="Permalink to &quot;ない（否定）／形容詞・名詞の四象限&quot;">​</a></h2><p><strong>規則：</strong> <strong>ない</strong> は「……ない／存在しない」という意味です。それ自体が <strong>I 類</strong>形容詞であり、ほかの形容詞の後（および名詞・II 類の文型）に付く<strong>補助形容詞</strong>として否定も表します。</p><p><strong>ない</strong> の後に <strong>です</strong> を付けると丁寧になり、<strong>ありません</strong> の形と対応します：</p><ul><li>非過去：<strong>ありません</strong> ＝ <strong>ないです</strong></li><li>過去：<strong>ありませんでした</strong> ＝ <strong>なかったです</strong></li></ul><p>時制（非過去／過去）× 肯否（肯定／否定）で、<strong>形容詞・名詞の四象限</strong>ができます。</p><h3 id="形容詞の四象限-丁寧" tabindex="-1">形容詞の四象限（丁寧） <a class="header-anchor" href="#形容詞の四象限-丁寧" aria-label="Permalink to &quot;形容詞の四象限（丁寧）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種類</th><th>時制</th><th>肯定</th><th>否定</th></tr></thead><tbody><tr><td>I 類（例：高い）</td><td>非過去</td><td>高いです</td><td>高くありません ／ 高くないです</td></tr><tr><td></td><td>過去</td><td>高かったです</td><td>高くありませんでした ／ 高くなかったです</td></tr><tr><td>II 類（例：静か）</td><td>非過去</td><td>静かです</td><td>静かではありません（じゃありません） ／ 静かではないです（じゃないです）</td></tr><tr><td></td><td>過去</td><td>静かでした</td><td>静かではありませんでした（じゃありませんでした） ／ 静かではなかったです（じゃなかったです）</td></tr></tbody></table><h3 id="名詞の四象限-丁寧" tabindex="-1">名詞の四象限（丁寧） <a class="header-anchor" href="#名詞の四象限-丁寧" aria-label="Permalink to &quot;名詞の四象限（丁寧）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種類</th><th>時制</th><th>肯定</th><th>否定</th></tr></thead><tbody><tr><td>名詞（例：学生）</td><td>非過去</td><td>学生です</td><td>学生ではありません（じゃありません） ／ 学生ではないです（じゃないです）</td></tr><tr><td></td><td>過去</td><td>学生でした</td><td>学生ではありませんでした（じゃありませんでした） ／ 学生ではなかったです（じゃなかったです）</td></tr></tbody></table><p>話し言葉では <strong>では</strong> を <strong>じゃ</strong> に替えられます。</p><h2 id="形容詞をつなぐ" tabindex="-1">形容詞をつなぐ <a class="header-anchor" href="#形容詞をつなぐ" aria-label="Permalink to &quot;形容詞をつなぐ&quot;">​</a></h2><p><strong>規則：</strong> 形容詞を並列・順接でつなぐときは、<strong>前の</strong>形容詞の<strong>連用形</strong>（中止形）を使います。形は前の形容詞だけで決まり、後に何が来るかには左右されません。時制は<strong>最後の</strong>述語が担い、途中の形は時制を表しません。</p><ul><li><p><strong>I 類：</strong> <strong>い</strong> を取って <strong>くて</strong>（A₁ い → く + て）</p></li><li><p><strong>II 類：</strong> <strong>A₂ + で</strong></p></li><li><p>映画の主人公は背が高くて、魅力的です。<em>（高くて = I 類；魅力的 = II 類）</em></p></li><li><p>昨日の試験問題は複雑で、難しかったです。<em>（複雑で = II 類；過去は 難しい の側に）</em></p></li><li><p>映画の主人公は背が高くて、かっこいいです。<em>（I 類 + I 類——やはり 高くて）</em></p></li><li><p>映画の主人公は背が高くて、魅力的です。<em>（I 類 + II 類——やはり 高くて）</em></p></li><li><p>昨日の映画の主人公は背が高くて、魅力的でした。<em>（途中は 高くて のまま；過去は でした だけ）</em></p></li></ul><h2 id="n-まで-終点" tabindex="-1">N まで（終点） <a class="header-anchor" href="#n-まで-終点" aria-label="Permalink to &quot;N まで（終点）&quot;">​</a></h2><p><strong>規則：</strong> <strong>まで</strong> は名詞の後に付いて<strong>終点・限度</strong>を表します。<strong>時間</strong>の名詞（この課）にも、空間的な終点を表す<strong>場所</strong>の名詞にも使います。<strong>N まで</strong> に <strong>です</strong> を付けて名詞述語文にすることもできます。</p><ul><li>わたしは昨日、遅くまで日本語の試験でした。</li><li>今日の授業はここまでです。</li><li>あの歌手のライブツアーは来月20日までです。</li></ul><h2 id="全然-形容詞-否定" tabindex="-1">全然 + 形容詞（否定） <a class="header-anchor" href="#全然-形容詞-否定" aria-label="Permalink to &quot;全然 + 形容詞（否定）&quot;">​</a></h2><p><strong>規則：</strong> <strong>あまり</strong> と同じく、<strong>全然</strong> は程度の副詞で、形容詞の<strong>否定</strong>形と一緒に使って「まったく……ない」という意味になります。話し言葉では <strong>全然</strong> だけで「まったく（そんなことはない）」と答えることもできます。</p><ul><li>A：昨日の試験は難しかったですか。</li><li>B：全然難しくなかったですよ。</li><li>わたしは運動が全然好きではありません。</li><li>彼女の料理は全然美味しくありません。</li><li>A：日本語の試験は難しかったですか。</li><li>B：ううん、全然。</li></ul><h2 id="n-とか-例を挙げる" tabindex="-1">N とか（例を挙げる） <a class="header-anchor" href="#n-とか-例を挙げる" aria-label="Permalink to &quot;N とか（例を挙げる）&quot;">​</a></h2><p><strong>規則：</strong> <strong>とか</strong> は名詞に付いて<strong>例を挙げます</strong>（……など）。話し言葉でよく使い、1 回だけでも複数回でも使えます。<strong>とか</strong> を使うときは、話題・主語・目的語の助詞 <strong>は / が / を</strong> を省略できます。</p><ul><li>A：どんな飲み物が好きですか。</li><li>B：ミルクティーとか、コーラとか。</li><li>木曜日の午後以降とかはどうですか。</li></ul><h2 id="形容詞が名詞を修飾する-連体形" tabindex="-1">形容詞が名詞を修飾する（連体形） <a class="header-anchor" href="#形容詞が名詞を修飾する-連体形" aria-label="Permalink to &quot;形容詞が名詞を修飾する（連体形）&quot;">​</a></h2><p><strong>規則：</strong> 形容詞は述語になるだけでなく、<strong>名詞の前</strong>に置いてその名詞を修飾することもできます。この形を<strong>連体形</strong>といいます。</p><ul><li><p><strong>I 類</strong>（イ形容詞）：<strong>A₁ + 名詞</strong>——形容詞は名詞に<strong>直接</strong>付きます（語尾の <strong>い</strong> はそのまま）。</p></li><li><p><strong>II 類</strong>（ナ形容詞）：<strong>A₂ + な + 名詞</strong>——名詞の前に <strong>な</strong> を入れます。そのため <strong>ナ形容詞</strong> と呼ぶ本もあります。</p></li><li><p>白いパソコン <em>（I 類：白い + パソコン）</em></p></li><li><p>きれいな町 <em>（II 類：きれい + な + 町）</em></p></li></ul><h2 id="n-が-主語-——主語を示す-は-と-が" tabindex="-1">N が（主語）——主語を示す は と が <a class="header-anchor" href="#n-が-主語-——主語を示す-は-と-が" aria-label="Permalink to &quot;N が（主語）——主語を示す は と が&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p>長く混同しやすい点：<strong>は</strong> も <strong>が</strong> も「主語」のように見えるものを示せますが、答える情報の種類が違います。<strong>が</strong> = 主語が聞き手にとって<strong>新しい・未知の</strong>情報（焦点は <strong>が</strong> の前の名詞）。<strong>は</strong> = 主語が<strong>すでに分かっている</strong>（旧情報）；焦点は <strong>は</strong> の<strong>後ろ</strong>に来る内容です。</p></div><p><strong>規則：</strong> 聞き手がまだ前提として持っていないものを導入したり特定したりするときは <strong>が</strong> を使います。それが会話の中で確立したら <strong>は</strong> に切り替えます。主語を尋ねる疑問詞の質問（<strong>だれが</strong>、<strong>何が</strong> など）には <strong>が</strong> を使い、答えでも特定されたものには <strong>が</strong> が付くのがふつうです。その人・ものについての次の文からは <strong>は</strong> を使います。</p><ul><li>ほら、あそこの男の人。あの人<strong>は</strong>中村さんのお兄さんですよ。<em>（あの人 はすでに指し示されている → <strong>は</strong>；焦点は彼が誰か。）</em></li><li>A：へえ、小学校の時の記念写真ですか。中村さんは、これ？</li><li>B：違いますよ。これ<strong>が</strong>わたしです。<em>（どれかを特定する → <strong>が</strong>；焦点は これ。）</em></li><li>こちらのパソコン<strong>が</strong>、今お得ですよ。<em>（これを新しい焦点として取り上げる → <strong>が</strong>。）</em></li><li>A：日本語<strong>は</strong>難しいですか。<em>（話題 = 日本語 → <strong>は</strong>。）</em></li><li>B：ええ、文法<strong>が</strong>難しいです。<em>（難しい部分を新しい焦点として特定する → <strong>が</strong>。）</em></li><li>A：だれ<strong>が</strong>留学生ですか。<em>（だれが——必ず <strong>が</strong>。）</em></li><li>B：あの人<strong>が</strong>留学生で、ジョージさんです。ジョージさん<strong>は</strong>今、先生の研究室にいます。<em>（<strong>が</strong> で特定し、その後は既知のジョージさん → <strong>は</strong>。）</em></li></ul><h2 id="n-と同じ-n-と同じ" tabindex="-1">N と同じ（N と同じ） <a class="header-anchor" href="#n-と同じ-n-と同じ" aria-label="Permalink to &quot;N と同じ（N と同じ）&quot;">​</a></h2><p><strong>規則：</strong> <strong>同じ</strong> は「同一である」という意味の <strong>II 類</strong>形容詞です。比べる名詞の後に <strong>と</strong> を付けます：<strong>N と同じ</strong>。</p><p><strong>例外（間違えやすい）：</strong> <strong>同じ</strong> が名詞を<strong>連体修飾</strong>するときは <strong>な</strong> を付け<strong>ません</strong>——<strong>同じ + 名詞</strong> と直接書きます（<em>同じな</em> とは言わない）。</p><ul><li>白いパソコンと同じ大きさです。</li><li>李さんは中村さんと同じ大学です。</li><li>経済学部は法学部と同じ建物です。</li></ul><h2 id="n-がほしいです-n-が欲しい" tabindex="-1">N がほしいです（N が欲しい） <a class="header-anchor" href="#n-がほしいです-n-が欲しい" aria-label="Permalink to &quot;N がほしいです（N が欲しい）&quot;">​</a></h2><p><strong>規則：</strong> <strong>ほしい</strong> は「（何かを）手に入れたい」という意味の <strong>I 類</strong>形容詞です。ほかの I 類形容詞と同じように活用します。欲しいものはふつう <strong>が</strong> で示します：<strong>N がほしいです</strong>。</p><p><strong>人称の制限：</strong> <strong>ほしい</strong> は主に<strong>話し手</strong>自身の望み（一人称）に使います。三人称の望みには使わないようにします。聞き手に尋ねるのは、主に親しい家族や友人の間なら問題ありません。</p><p><strong>ほしい</strong> は名詞を連体修飾することもできます（<strong>ほしい + 名詞</strong>）。</p><ul><li>（私は）新しいスーツケースがほしいです。</li><li>地下鉄がなかった時は、車がほしかったです。</li><li>A：ほしいものはありますか。</li><li>B：ありますよ。お金がほしいです。</li></ul><h2 id="節1-が、節2-逆接・前置き" tabindex="-1">節₁ が、節₂（逆接・前置き） <a class="header-anchor" href="#節1-が、節2-逆接・前置き" aria-label="Permalink to &quot;節₁ が、節₂（逆接・前置き）&quot;">​</a></h2><p><strong>規則：</strong> 文中の <strong>が</strong> は 2 つの節を<strong>対比・逆接</strong>の意味でつなぐことができます（「……が、……」）。<strong>すみませんが</strong>／<strong>失礼ですが</strong> のような決まった言い方の後では、語調を和らげる前置きになり、逆接の意味は弱く、「しかし」と訳さなくてよいことが多いです。節₂ を<strong>省略</strong>して、文末に <strong>が</strong> を残すと、依頼や希望を和らげる表現になります。</p><ul><li>歴史の授業は難しいですが、面白いです。</li><li>失礼ですが、お名前は？</li><li>新しいパソコンがほしいのですが。<em>（節₂ を言わずに残す／柔らかい依頼。）</em></li></ul><h2 id="n1-も-n2-も-n1-も-n2-も" tabindex="-1">N₁ も N₂ も（N₁ も N₂ も） <a class="header-anchor" href="#n1-も-n2-も-n1-も-n2-も" aria-label="Permalink to &quot;N₁ も N₂ も（N₁ も N₂ も）&quot;">​</a></h2><p><strong>規則：</strong> 並列する 2 つの名詞のそれぞれに <strong>も</strong> を付けます：<strong>N₁ も N₂ も ～</strong>。両方が同じ述語を共有することを表します。</p><ul><li>兄も姉も会社員です。</li><li>日本料理も中華料理も美味しいです。</li><li>メモリーもストレージも大きいです。</li></ul><h2 id="比較の文型-比較" tabindex="-1">比較の文型（比較） <a class="header-anchor" href="#比較の文型-比較" aria-label="Permalink to &quot;比較の文型（比較）&quot;">​</a></h2><p>日本語には 2 つの名詞を比べる決まった文型がいくつかあります。以下の 4 つがこの課の中心です。</p><h3 id="_1-n1-は-n2-より" tabindex="-1">(1) N₁ は N₂ より ～ <a class="header-anchor" href="#_1-n1-は-n2-より" aria-label="Permalink to &quot;(1) N₁ は N₂ より ～&quot;">​</a></h3><p><strong>規則：</strong> <strong>より</strong> は比較の<strong>基準</strong>を示します。<strong>N₁ は N₂ より ～</strong> は、述語の性質を N₁ のほうが N₂ より多く持っていることを表します。差が大きいときは <strong>ずっと</strong> を加えます。</p><ul><li>中国は日本より広いです。</li><li>（こちらのパソコンは）さっきのよりメモリーがずっと大きいですよ。</li><li>スマホはパソコンより値段が高いです。</li></ul><h3 id="_2-n2-より-n1-のほうが" tabindex="-1">(2) N₂ より N₁ のほうが ～ <a class="header-anchor" href="#_2-n2-より-n1-のほうが" aria-label="Permalink to &quot;(2) N₂ より N₁ のほうが ～&quot;">​</a></h3><p><strong>規則：</strong> 同じ比較を別の形で言います：<strong>N₂ より N₁ のほうが ～</strong>。<strong>ほう</strong>（方）は「二つのうちの一方」という意味です。文型 (4) への<strong>答え</strong>によく使い、答えでは <strong>N₂ より</strong> を省いて <strong>N₁ のほうが ～</strong> とすることが多いです。</p><ul><li>日本より中国のほうが広いです。</li><li>パソコンよりスマホのほうが値段が高いです。</li></ul><h3 id="_3-n2-は-n1-ほど-否定" tabindex="-1">(3) N₂ は N₁ ほど ～（否定） <a class="header-anchor" href="#_3-n2-は-n1-ほど-否定" aria-label="Permalink to &quot;(3) N₂ は N₁ ほど ～（否定）&quot;">​</a></h3><p><strong>規則：</strong> 名詞の後の <strong>ほど</strong> は<strong>程度</strong>を表します。<strong>否定</strong>の述語と一緒に使うと、<strong>N₂ は N₁ ほど ～ない</strong> は N₂ が N₁ の程度に<strong>達しない</strong>ことを表します。</p><ul><li>日本は中国ほど広くありません。</li><li>パソコンはスマホほど値段が高くありません。</li></ul><h3 id="_4-n1-と-n2-とどちら-のほう-が-か" tabindex="-1">(4) N₁ と N₂ とどちら（のほう）が ～か <a class="header-anchor" href="#_4-n1-と-n2-とどちら-のほう-が-か" aria-label="Permalink to &quot;(4) N₁ と N₂ とどちら（のほう）が ～か&quot;">​</a></h3><p><strong>規則：</strong> 2 つのうちどちらがより……かを尋ねます：<strong>N₁ と N₂ とどちら（のほう）が ～か</strong>。答えには文型 (2) を使い、ふつうは <strong>N のほうが ～</strong> だけで答えます。</p><ul><li>A：中国と日本とどちら（のほう）が広いですか。</li><li>B：中国のほうが広いです。</li><li>A：パソコンとスマホとどちらが高いですか。</li><li>B：スマホのほうが高いです。</li></ul><h2 id="n-なので、-原因・理由-ii" tabindex="-1">N なので、～（原因・理由 II） <a class="header-anchor" href="#n-なので、-原因・理由-ii" aria-label="Permalink to &quot;N なので、～（原因・理由 II）&quot;">​</a></h2><p><strong>規則：</strong> <strong>ので</strong> は 2 つの節をつないで原因とその結果を表します。名詞述語では <strong>N + な + ので</strong> を使い、「N なので、……」という意味になります（第 5 課の文法 1 を参照）。<strong>から</strong>（第 9 課の文法 4）と比べると、<strong>ので</strong> は客観的な原因を強調し、より柔らかく改まった響きになります。</p><ul><li>僕は神奈川県の湘南の出身なので、僕も『スラムダンク』が大好きですよ。</li><li>雨なので、運動会は中止です。</li><li>学生なので、お金がないです。</li></ul><h2 id="n-が-対象を示す-が-iii" tabindex="-1">N が～（対象を示す が III） <a class="header-anchor" href="#n-が-対象を示す-が-iii" aria-label="Permalink to &quot;N が～（対象を示す が III）&quot;">​</a></h2><p><strong>規則：</strong> 助詞 <strong>が</strong> は主語のほかに対象を示すこともできます。この課では、<strong>が</strong> は能力や技能の程度の対象を示します。こうした表現は主に <strong>II 類（ナ）形容詞</strong>と<strong>動詞</strong>です。</p><ul><li><p><strong>II 類（ナ）形容詞：</strong> N が 上手／下手、好き／嫌い、得意／苦手 です。</p></li><li><p><strong>動詞：</strong> N が できます、わかります。</p></li><li><p>私は運動が嫌いです。</p></li><li><p>辛いものが苦手です。</p></li><li><p>兄は歴史が得意です。</p></li><li><p>先生の話がよくわかりません。</p></li><li><p>父は料理ができます。</p></li></ul><h2 id="n1の中で-n2がいちばん-最上級-で-は範囲を示す" tabindex="-1">（N₁の中で）N₂がいちばん～（最上級；で は範囲を示す） <a class="header-anchor" href="#n1の中で-n2がいちばん-最上級-で-は範囲を示す" aria-label="Permalink to &quot;（N₁の中で）N₂がいちばん～（最上級；で は範囲を示す）&quot;">​</a></h2><p><strong>規則：</strong> 比較の文型を土台にした<strong>最上級</strong>です：<strong>N₁</strong> が示す範囲の中で、述語が表す性質を <strong>N₂</strong> が最も多く持っていることを表します。名詞の後の助詞 <strong>で</strong> は範囲を限定し、副詞 <strong>いちばん</strong> は「最も」という意味です。最上級は 3 つ以上の人やものの中から最も際立つものを取り出します。</p><ul><li>日本の漫画の中で、『スラムダンク』がいちばん好きです。</li><li>スポーツの中でバスケットボールがいちばん好きです。</li><li>クラスの中で、李さんがいちばん頭がいいです。</li><li>日本料理の中で、お寿司がいちばん好きです。</li></ul><h2 id="は-が、-は-。-対比の-は-ii" tabindex="-1">～は～が、～は～。（対比の は II） <a class="header-anchor" href="#は-が、-は-。-対比の-は-ii" aria-label="Permalink to &quot;～は～が、～は～。（対比の は II）&quot;">​</a></h2><p><strong>規則：</strong> <strong>が</strong>（逆接）でつながる文で、2 つの節が似た形をしていて互いに対比しているとき、両方の話題を <strong>は</strong> で示します。<strong>は … は</strong> の組み合わせが対比を担います。</p><ul><li>バスケットボールはできませんが、サッカーとテニスはすこしできます。</li><li>日本語は上手ですが、英語は下手です。</li><li>昨日は寒かったですが、今日はとても暑いです。</li><li>私は学生ですが、妹は会社員です。</li></ul><h2 id="n-に-状態や性質の対象" tabindex="-1">N に～（状態や性質の対象） <a class="header-anchor" href="#n-に-状態や性質の対象" aria-label="Permalink to &quot;N に～（状態や性質の対象）&quot;">​</a></h2><p><strong>規則：</strong> 名詞の後の助詞 <strong>に</strong> は、後に続く能力、態度、性質が向けられる対象を示します。述語はふつう 必要、便利、詳しい のような<strong>性質</strong>、<strong>状態</strong>、<strong>能力</strong>を表す形容詞です。</p><ul><li>マスクは外出に必要です。</li><li>横の中国語訳は日本語学習に便利です。</li><li>兄は中国の歴史にも、日本の歴史にも詳しいです。</li><li>駅の近くのアパートは、買い物に便利です。</li></ul><h2 id="の-ん-です-説明-i-形容詞と名詞" tabindex="-1">～の（／ん）です（説明 I：形容詞と名詞） <a class="header-anchor" href="#の-ん-です-説明-i-形容詞と名詞" aria-label="Permalink to &quot;～の（／ん）です（説明 I：形容詞と名詞）&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p>この課で最も重要な文型です。<strong>～の（／ん）です</strong> は、ふつうの叙述を<strong>説明</strong>に変えます。事実を、状況の背後にある理由、背景、「実は……」として示すのです。話し言葉ではふつう <strong>～んです</strong> と縮めます。中国語や英語には直接対応する表現がないので、ふつうは訳しません。</p></div><p><strong>接続：</strong></p><ul><li>N + な + の（／ん）です</li><li>Aɪ（イ形容詞）+ の（／ん）です</li><li>Aɪɪ（ナ形容詞）+ な + の（／ん）です</li></ul><p><strong>規則：</strong> この文型は会話でとてもよく使います。<strong>形容詞の連体形</strong>または <strong>N + な</strong> に付き、話し言葉では <strong>～んです</strong> が好まれます。話し手自身の考えを述べたり、状況を説明・解明したりします。主な用法は 3 つです。</p><h3 id="_1-状況の説明・理由の提示" tabindex="-1">(1) 状況の説明・理由の提示 <a class="header-anchor" href="#_1-状況の説明・理由の提示" aria-label="Permalink to &quot;(1) 状況の説明・理由の提示&quot;">​</a></h3><p>すでに話題になったことの背後にある<strong>理由や原因</strong>を示します。主に話し手自身の事情を説明するのに使います。</p><ul><li>実は『キャプテン翼』も『テニスの王子様』も好きなんですよ。</li><li>すみません、今はちょっと忙しいんです。</li><li>私は冷たい飲み物が苦手なんです。</li></ul><h3 id="_2-納得・気づき" tabindex="-1">(2) 納得・気づき <a class="header-anchor" href="#_2-納得・気づき" aria-label="Permalink to &quot;(2) 納得・気づき&quot;">​</a></h3><p>前に言われたことが のです の文の理由になります。話し手は「そういうことか」のように結論を<strong>受け入れたり確認したり</strong>するのに使い、自分の推測を確かめることが多いです。</p><ul><li>由加さんは本当に漫画ファンなのですね。</li></ul><h3 id="_3-遠回しな提案・依頼の前置き" tabindex="-1">(3) 遠回しな提案・依頼の前置き <a class="header-anchor" href="#_3-遠回しな提案・依頼の前置き" aria-label="Permalink to &quot;(3) 遠回しな提案・依頼の前置き&quot;">​</a></h3><p><strong>～の（／ん）ですが、～</strong> は先に背景を示し、話し手が本当に望むことをそれにつなげます。文が <strong>が</strong> で止まり、依頼の内容を聞き手が察することも多いです。</p><ul><li>新しいパソコンがほしいのですが。（店員に）</li><li>マックの最新モデルがいちばん軽いのですが。（検討してはどうか）</li><li>あのう、テレビの音が大きいのですが。（音を小さくしてほしい）</li></ul><p><strong>メモ：</strong> 1 つ目の例は、店員に自分の希望を伝える言い方です。2 つ目は、事実を説明しながら「検討してはどうか」とほのめかしています。3 つ目は状況を丁寧に述べて、音量を下げてほしいという依頼を含ませています。</p><h2 id="n-場所-へ-に-移動動詞-移動の方向" tabindex="-1">N（場所）＋へ（／に）＋移動動詞（移動の方向） <a class="header-anchor" href="#n-場所-へ-に-移動動詞-移動の方向" aria-label="Permalink to &quot;N（場所）＋へ（／に）＋移動動詞（移動の方向）&quot;">​</a></h2><p><strong>規則：</strong> 場所を表す名詞の後の助詞 <strong>へ</strong> は移動の<strong>方向</strong>を示します。<strong>行く</strong>、<strong>来る</strong>、<strong>帰る</strong> などの移動動詞と一緒に使います。この用法の <strong>へ</strong> は <em>he</em> ではなく <strong>e</strong> と発音します。<strong>へ</strong> は <strong>に</strong> に替えることもできます。</p><ul><li>毎朝、会社へ行きます。</li><li>いつ帰りますか。</li><li>去年、家族と大阪に来ました。</li></ul><h2 id="疑問詞-も-全部否定" tabindex="-1">疑問詞 ＋ も（全部否定） <a class="header-anchor" href="#疑問詞-も-全部否定" aria-label="Permalink to &quot;疑問詞 ＋ も（全部否定）&quot;">​</a></h2><p><strong>規則：</strong> <strong>疑問詞 + も</strong> を<strong>否定の述語</strong>と一緒に使うと全部否定になります。誰も、何も、どれも、どこにも などです。<strong>に</strong> のような助詞は疑問詞と <strong>も</strong> の間に入れます（どこ<strong>に</strong>も）。</p><ul><li>夜中の博物館には誰もいません。</li><li>引き出しには何もありません。</li><li>ここのカレー料理はどれもおいしくないです。</li><li>この週末はどこにも行きません。</li></ul><h2 id="疑問詞-か-不定" tabindex="-1">疑問詞 ＋ か（不定） <a class="header-anchor" href="#疑問詞-か-不定" aria-label="Permalink to &quot;疑問詞 ＋ か（不定）&quot;">​</a></h2><p><strong>規則：</strong> <strong>疑問詞 + か</strong> は<strong>不定</strong>を表します。誰か、何人か、いくつか、何回か などです。<strong>平叙文</strong>でも疑問文でも使えます。<strong>疑問詞か</strong> が疑問文に出てくると、ふつうの<strong>はい・いいえ疑問文</strong>になるので、答えはふつう <strong>はい</strong> か <strong>いいえ</strong> で始まります。疑問詞 + も + 否定（「誰も……ない」）と比べてみてください。</p><ul><li>あのレストランにお客さんが何人かいます。</li><li>特に重要な理由がいくつかあります。</li><li>A：あのう、すみません。誰かいますか。</li><li>B：はい。</li><li>以前、何回か来ました。</li></ul><h2 id="n-から-起点" tabindex="-1">N から（起点） <a class="header-anchor" href="#n-から-起点" aria-label="Permalink to &quot;N から（起点）&quot;">​</a></h2><p><strong>規則：</strong> <strong>時間</strong>、<strong>場所</strong>、<strong>順序</strong>を表す名詞の後の助詞 <strong>から</strong> は<strong>起点</strong>を示します。<strong>から</strong> の後に直接 <strong>です</strong> を付けて名詞述語文（「N から始まる」）にすることもできます。起点の <strong>から</strong> は終点の <strong>まで</strong> とも組み合わせます：<strong>N₁ から N₂ まで</strong>。</p><ul><li>体のトレーニングは明日からです。</li><li>今から成績の発表です。</li><li>ここからはテストの内容です。</li><li>会議は今月の4日から6日までです。</li></ul><h2 id="n-じゃありませんか-驚きの「-じゃないか」" tabindex="-1">N じゃありませんか（驚きの「……じゃないか」） <a class="header-anchor" href="#n-じゃありませんか-驚きの「-じゃないか」" aria-label="Permalink to &quot;N じゃありませんか（驚きの「……じゃないか」）&quot;">​</a></h2><p><strong>規則：</strong> 名詞文 <strong>N です</strong> の<strong>反語</strong>の形で、「N ではないか」「なんと N だ」という意味です。実際には何も尋ねておらず、<strong>驚きや感嘆</strong>を表します。主に<strong>話し言葉</strong>で使います。</p><ul><li>とても有名な研究所じゃありませんか。</li><li>もう12時50分じゃありませんか。</li><li>あ、あの人は、鈴木さんじゃありませんか。</li></ul><h2 id="けど。-文末の柔らかい逆接" tabindex="-1">…けど。（文末の柔らかい逆接） <a class="header-anchor" href="#けど。-文末の柔らかい逆接" aria-label="Permalink to &quot;…けど。（文末の柔らかい逆接）&quot;">​</a></h2><p><strong>規則：</strong> 接続助詞 <strong>けど</strong> は <strong>けれども</strong> の縮約形で、逆接を表します。ここでは<strong>文末</strong>に置かれ、<strong>柔らかい逆接</strong>になります：話し手は途中で言いさし、後半を言わずに残します。そうすると語調が<strong>穏やかで遠回し</strong>になり、主に話し言葉で使います。けれども は <strong>けど</strong> のほかに <strong>けれど</strong>、<strong>けども</strong> とも縮まります。</p><ul><li>これから会議なんですけど。（だから、差し支えなければ）</li><li>そろそろお時間ですけれども。</li><li>A：中村さんはいますか。</li><li>B：はい、私ですけど。（何でしょうか）</li></ul><hr><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>ここから動詞（動詞）。</strong> ここまでは名詞、形容詞、助詞を扱いました。ここからは動詞を扱います。</p></div><h2 id="動詞の活用分類-動詞の活用分類" tabindex="-1">動詞の活用分類（動詞の活用分類） <a class="header-anchor" href="#動詞の活用分類-動詞の活用分類" aria-label="Permalink to &quot;動詞の活用分類（動詞の活用分類）&quot;">​</a></h2><p><strong>規則：</strong> 動詞を<strong>活用の種類</strong>で分けることが、動詞文をうまく使う第一歩です。日本の伝統的な学校文法と、現在よく使われる教科書とでは動詞の分け方が少し違いますが、ほとんどは<strong>名前</strong>が違うだけです。<strong>辞書形</strong>（<strong>基本形</strong>ともいう）は、辞書の見出しとしての活用しない形です。</p><table tabindex="0"><thead><tr><th>種類</th><th>日本語の名称</th><th>形</th><th>例</th></tr></thead><tbody><tr><td>I 類</td><td>五段動詞</td><td>辞書形が <strong>ウ段の仮名</strong>で終わる</td><td>休む、願う、わかる、ある</td></tr><tr><td>II 類</td><td>一段動詞</td><td>辞書形が <strong>る</strong> で終わり、その前が <strong>イ段またはエ段の仮名</strong></td><td>寝る、起きる、忘れる</td></tr><tr><td>III 類</td><td>サ変動詞</td><td><strong>する</strong> 単独、または <strong>漢語 + する</strong></td><td>する、勉強する、運動する、運転する</td></tr><tr><td>III 類</td><td>カ変動詞</td><td><strong>来る</strong> の 1 語だけ</td><td>来る</td></tr></tbody></table><h2 id="v-ます形-丁寧形とます形の語幹" tabindex="-1">V ます形（丁寧形とます形の語幹） <a class="header-anchor" href="#v-ます形-丁寧形とます形の語幹" aria-label="Permalink to &quot;V ます形（丁寧形とます形の語幹）&quot;">​</a></h2><p><strong>規則：</strong> 使うときは、ふつう辞書形をもとに丁寧の語尾 <strong>ます</strong> を付けます。<strong>ます</strong> を付ける前に、動詞は<strong>活用の種類</strong>（上の表を参照）に応じて形を変えます。この変化を<strong>動詞の活用</strong>といいます。</p><h3 id="i-類-五段動詞" tabindex="-1">I 類（五段動詞） <a class="header-anchor" href="#i-類-五段動詞" aria-label="Permalink to &quot;I 類（五段動詞）&quot;">​</a></h3><p>最後の仮名を <strong>ウ段</strong>から対応する <strong>イ段</strong>の仮名に変え、<strong>ます</strong> を付けます。</p><ul><li>休む：む → み + ます = 休みます</li><li>願う：う → い + ます = 願います</li><li>ある：る → り + ます = あります</li></ul><h3 id="ii-類-一段動詞" tabindex="-1">II 類（一段動詞） <a class="header-anchor" href="#ii-類-一段動詞" aria-label="Permalink to &quot;II 類（一段動詞）&quot;">​</a></h3><p>最後の <strong>る</strong> を取り、<strong>ます</strong> を付けます。</p><ul><li>起きる：る を取る + ます = 起きます</li><li>寝る：る を取る + ます = 寝ます</li><li>忘れる：る を取る + ます = 忘れます</li></ul><h3 id="iii-類-サ変・カ変" tabindex="-1">III 類（サ変・カ変） <a class="header-anchor" href="#iii-類-サ変・カ変" aria-label="Permalink to &quot;III 類（サ変・カ変）&quot;">​</a></h3><ul><li><strong>サ変 する：</strong> する → し + ます = します；勉強する → 勉強し + ます = 勉強します</li><li><strong>カ変 来る：</strong> 来る（くる）→ 来（き）+ ます = 来ます（きます）</li></ul><h3 id="ます形の語幹" tabindex="-1">ます形の語幹 <a class="header-anchor" href="#ます形の語幹" aria-label="Permalink to &quot;ます形の語幹&quot;">​</a></h3><p>丁寧形から <strong>ます</strong> を取った残りが<strong>ます形の語幹</strong>で、このノートでは <strong>V ます形</strong> と表記します。学校文法では <strong>（第一）連用形</strong> と呼びます。たとえば ある の丁寧形は <strong>あります</strong> なので、ます形の語幹は <strong>あり</strong> です。</p><table tabindex="0"><thead><tr><th>種類</th><th>辞書形</th><th>丁寧形</th><th>ます形の語幹（連用形）</th></tr></thead><tbody><tr><td>I 類</td><td>わかる</td><td>わかります</td><td>わかり</td></tr><tr><td>II 類</td><td>忘れる</td><td>忘れます</td><td>忘れ</td></tr><tr><td>III 類</td><td>する</td><td>します</td><td>し</td></tr><tr><td>III 類</td><td>来る（くる）</td><td>来ます（きます）</td><td>来（き）</td></tr></tbody></table><h2 id="n-時間-に-時点" tabindex="-1">N（時間）に（時点） <a class="header-anchor" href="#n-時間-に-時点" aria-label="Permalink to &quot;N（時間）に（時点）&quot;">​</a></h2><p><strong>規則：</strong> 時間を表す名詞の後の助詞 <strong>に</strong> は、動作が起こる<strong>時点</strong>を示します。</p><ul><li>日曜日の午後1時半に会いましょうか。</li><li>いつも夜9時に寝ます。</li><li>13日に中村さんの誕生日パーティーがあります。</li></ul><h2 id="n-時間-ごろ-おおよその時刻" tabindex="-1">N（時間）＋ごろ（おおよその時刻） <a class="header-anchor" href="#n-時間-ごろ-おおよその時刻" aria-label="Permalink to &quot;N（時間）＋ごろ（おおよその時刻）&quot;">​</a></h2><p><strong>規則：</strong> 接尾辞 <strong>ごろ</strong>（<strong>頃</strong> とも書く）は、具体的な時間の名詞の後に付いて、その時刻の**「前後」<strong>を表します。<strong>ごろ</strong> を使うときは、時点の助詞 <strong>に</strong> を</strong>省略**できます：2時ごろ帰ります も 2時ごろに帰ります も使えます。</p><ul><li>いつも夜11時ごろ寝ます。</li><li>今日は2時ごろに帰ります。</li><li>3月ごろ、桜が咲きます。</li><li>2000年ごろから、車が多くなりました。</li></ul><h2 id="数量詞-くらい-ぐらい-およそ" tabindex="-1">数量詞＋くらい／ぐらい（およそ） <a class="header-anchor" href="#数量詞-くらい-ぐらい-およそ" aria-label="Permalink to &quot;数量詞＋くらい／ぐらい（およそ）&quot;">​</a></h2><p><strong>規則：</strong> <strong>くらい</strong>（<strong>ぐらい</strong> とも）は、時間、金額、数を表す数量詞の後に付いて、その量の**「およそ」**を表します。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>ごろ</strong> と比べてみましょう：ごろ はおおよその<strong>時点</strong>（2時ごろ）、くらい はおおよその<strong>量や長さ</strong>（2時間ぐらい）を表します。</p></div><ul><li>発表は全部で2時間ぐらいでした。</li><li>食費は毎月3万円ぐらいです。</li><li>教室には学生が5人ぐらいいます。</li></ul><h2 id="なる-状態の変化" tabindex="-1">なる（状態の変化） <a class="header-anchor" href="#なる-状態の変化" aria-label="Permalink to &quot;なる（状態の変化）&quot;">​</a></h2><p><strong>規則：</strong> <strong>なる</strong> は、ものやその状態が<strong>自然に変化する</strong>ことを表します。名詞、形容詞、動詞と組み合わせます。この課では名詞と形容詞を扱います。</p><table tabindex="0"><thead><tr><th>品詞</th><th>文型</th><th>例</th></tr></thead><tbody><tr><td>名詞</td><td><strong>N ＋ に ＋ なる</strong></td><td>会社員 → 会社員になる</td></tr><tr><td>イ形容詞</td><td><strong>い を取って → く ＋ なる</strong></td><td>寒い → 寒くなる</td></tr><tr><td>ナ形容詞</td><td><strong>A ＋ に ＋ なる</strong></td><td>静か → 静かになる</td></tr></tbody></table><ul><li>11月の初めから寒くなります。</li><li>体調が大分よくなりました。</li><li>日本語がかなり上手になりました。</li><li>今週末のイベントは中止になりました。</li><li>でも、午後から眠くなるから、何もできなくなります。</li></ul><p><strong>メモ：</strong> 何もできなくなります は「何もできない状態になる」という意味です。できない は <strong>できる</strong> の否定形です。否定の ない の形に なる が続くと、<strong>ない は なく に変わります</strong>：できない → <strong>できなくなる</strong>（できない状態への変化）。</p><h2 id="vましょう-vましょうか-勧誘-ましょう-ましょうか" tabindex="-1">Vましょう／Vましょうか（勧誘：……ましょう／……ましょうか） <a class="header-anchor" href="#vましょう-vましょうか-勧誘-ましょう-ましょうか" aria-label="Permalink to &quot;Vましょう／Vましょうか（勧誘：……ましょう／……ましょうか）&quot;">​</a></h2><p><strong>規則：</strong> <strong>ます形の語幹 ＋ ましょう</strong> は、聞き手に<strong>一緒に</strong>何かをしようと誘う表現で、<strong>いっしょに</strong> とよく一緒に使います。疑問の助詞 <strong>か</strong> を付けた <strong>Vましょうか</strong> は、相手が同意するかどうかを尋ねる形になり、より<strong>柔らかく</strong>なります。</p><ul><li>そろそろ帰りましょう。</li><li>A：昼休みは、あそこの店へ行きましょうか。</li><li>B：そうしましょう。</li><li>A：今晩、家でゲームしましょうか。</li><li>B：いいですね。</li></ul><h2 id="ほうがいい-助言-ほうがいい、名詞と形容詞" tabindex="-1">～ほうがいい（助言：……ほうがいい、名詞と形容詞） <a class="header-anchor" href="#ほうがいい-助言-ほうがいい、名詞と形容詞" aria-label="Permalink to &quot;～ほうがいい（助言：……ほうがいい、名詞と形容詞）&quot;">​</a></h2><p><strong>規則：</strong> <strong>ほう</strong> は「方向・一方」という意味です。<strong>ほうがいい</strong> を付けると、話し手から聞き手への<strong>助言</strong>になります。</p><table tabindex="0"><thead><tr><th>品詞</th><th>文型</th><th>例</th></tr></thead><tbody><tr><td>名詞</td><td><strong>N ＋ の ＋ ほうがいい</strong></td><td>効率的なもの → 効率的なもののほうがいい</td></tr><tr><td>イ形容詞</td><td><strong>辞書形 ＋ ほうがいい</strong></td><td>近い → 近いほうがいい</td></tr><tr><td>ナ形容詞</td><td><strong>A ＋ な ＋ ほうがいい</strong></td><td>安全 → 安全なほうがいい</td></tr></tbody></table><ul><li>もっと効率的なもののほうがいいですよ。</li><li>新しいアパートは会社に近いほうがいいです。</li><li>毎日の食材は安全なほうがいいです。</li></ul><h2 id="他動詞と-を-直接目的語を示す" tabindex="-1">他動詞と を（直接目的語を示す） <a class="header-anchor" href="#他動詞と-を-直接目的語を示す" aria-label="Permalink to &quot;他動詞と を（直接目的語を示す）&quot;">​</a></h2><p><strong>規則：</strong> 日本語の動詞には<strong>自動詞</strong>と<strong>他動詞</strong>があります。自動詞は直接目的語をとらず、他動詞はとることができます。両方の使い方がある動詞もあります。他動詞を使うときは、直接目的語になる名詞の後に <strong>を</strong> を付けます。</p><ul><li>本を読みます。</li><li>資料を調べます。</li></ul><p>直接目的語が<strong>話題</strong>になるときや「……も」を表すときは、<strong>を</strong> を <strong>は</strong> や <strong>も</strong> に替えられます。</p><ul><li>メールはよく送りますが、手紙はあまり書きません。</li><li>休みの日は、よく映画を見ます。買い物もします。</li></ul><h2 id="n-で-動作の場所-手段・道具" tabindex="-1">N で（動作の場所；手段・道具） <a class="header-anchor" href="#n-で-動作の場所-手段・道具" aria-label="Permalink to &quot;N で（動作の場所；手段・道具）&quot;">​</a></h2><h3 id="動作の場所" tabindex="-1">動作の場所 <a class="header-anchor" href="#動作の場所" aria-label="Permalink to &quot;動作の場所&quot;">​</a></h3><p><strong>規則：</strong> 場所の名詞の後に <strong>で</strong> を付けて、<strong>動作が行われる場所</strong>を示します。</p><ul><li>伊藤先生のゼミでデータを集めました。</li><li>私はよく喫茶店で小説を読みます。</li><li>日本では、口頭試験はどんな準備をしますか。</li></ul><h3 id="手段・道具" tabindex="-1">手段・道具 <a class="header-anchor" href="#手段・道具" aria-label="Permalink to &quot;手段・道具&quot;">​</a></h3><p><strong>規則：</strong> 名詞の後に <strong>で</strong> を付けて、<strong>動作に使う道具や手段</strong>を示します。</p><ul><li>スマホで外国語を勉強します。</li><li>インターネットで資料を調べます。</li><li>日本人はお箸で料理を食べます。</li></ul><h2 id="n-に-動作の相手・対象" tabindex="-1">N に（動作の相手・対象） <a class="header-anchor" href="#n-に-動作の相手・対象" aria-label="Permalink to &quot;N に（動作の相手・対象）&quot;">​</a></h2><p><strong>規則：</strong> 名詞の後に <strong>に</strong> を付けて、<strong>動作が向けられる人</strong>を示します。動詞によって、その人は何かを受け取る人、会う人、尋ねる相手などになります。</p><ul><li>中村さんにメールで資料を送ります。</li><li>午後、ジョージさんに会います。</li><li>友達に簡単なやり方を聞きます。</li></ul><h2 id="n-なら-話題を取り上げる" tabindex="-1">N なら（話題を取り上げる） <a class="header-anchor" href="#n-なら-話題を取り上げる" aria-label="Permalink to &quot;N なら（話題を取り上げる）&quot;">​</a></h2><p><strong>規則：</strong> 名詞の後に <strong>なら</strong> を付けて、その名詞を後に続く内容の<strong>話題</strong>として取り上げます。話題はすでに話に出たものか、会話から聞き手が推測できるものであることが多いです。<strong>N なら、～</strong> は「N について言えば……」、または相手の関心や依頼に応じて「N のことなら……」という意味になります。</p><ul><li>日本語の小説なら、家には何冊かありますよ。</li><li>A：新しいパソコンがほしいんですが。</li><li>B：パソコンなら、こちらがいいですよ。</li><li>A：一緒に喫茶店に行きましょうか。</li><li>B：コーヒーなら、スタバのがいいですね。</li></ul><h2 id="n-について-話題について" tabindex="-1">N について（話題について） <a class="header-anchor" href="#n-について-話題について" aria-label="Permalink to &quot;N について（話題について）&quot;">​</a></h2><p><strong>規則：</strong> 名詞の後に <strong>について</strong> を付けて、論じられている主題を示します。<strong>です</strong> を続けて述語にすることも、その話題について誰かが言う・書く・尋ねる内容を表す動詞句の前に置くこともできます。</p><ul><li>経済のグローバリゼーションについてです。</li><li>先週の旅行について作文を書きました。</li><li>今日の授業について、何か質問はありますか。</li></ul><h2 id="v-ます形の語幹-動作性名詞-に-移動動詞-移動の目的" tabindex="-1">V ます形の語幹／動作性名詞 ＋ に ＋ 移動動詞（移動の目的） <a class="header-anchor" href="#v-ます形の語幹-動作性名詞-に-移動動詞-移動の目的" aria-label="Permalink to &quot;V ます形の語幹／動作性名詞 ＋ に ＋ 移動動詞（移動の目的）&quot;">​</a></h2><p><strong>規則：</strong> 動詞の<strong>ます形の語幹</strong>または活動を表す名詞の後に <strong>に</strong> を付け、<strong>行く</strong>、<strong>来る</strong>、<strong>帰る</strong> などの移動動詞を続けます。移動の<strong>目的</strong>（「……しに行く・来る」）を表します。<strong>する</strong> 動詞を動作性名詞として使うときは、<strong>に</strong> の前には <strong>する</strong> を付けずに名詞の部分だけを使います。</p><ul><li>教室に忘れ物を取りに行きます。</li><li>サークルの仲間たちとお花見に行きます。</li><li>昨日中村さんのお家に遊びに行きました。</li><li>散歩に出かけましょうか。</li><li>資料を届けに来ました。</li></ul><h2 id="v-ます形の語幹-ながら-2-つのことを同時に" tabindex="-1">V ます形の語幹 ＋ ながら（2 つのことを同時に） <a class="header-anchor" href="#v-ます形の語幹-ながら-2-つのことを同時に" aria-label="Permalink to &quot;V ます形の語幹 ＋ ながら（2 つのことを同時に）&quot;">​</a></h2><p><strong>規則：</strong> 動詞の<strong>ます形の語幹</strong>に <strong>ながら</strong> を付けて、2 つの動作が<strong>同時に</strong>行われる、または交互に続くことを表します。</p><ul><li>考えながら、パワーポイントを作ります。</li><li>弟はいつも音楽を聴きながら、宿題をします。</li><li>お茶をしながら、話しましょうか。</li></ul><h2 id="数量表現-も-主観的に多い量" tabindex="-1">数量表現 ＋ も（主観的に多い量） <a class="header-anchor" href="#数量表現-も-主観的に多い量" aria-label="Permalink to &quot;数量表現 ＋ も（主観的に多い量）&quot;">​</a></h2><p><strong>規則：</strong> 数量表現の後に <strong>も</strong> を付けて、話し手がその量を<strong>多い、予想以上だ</strong>と感じていることを表します。数字そのものが客観的に大きい必要はありません：文脈上 3 人が多いと感じられれば、<strong>３人も</strong> で「3 人もいる」という気持ちを表せます。</p><ul><li>教室に学生が３人もいます。</li><li>議論は３日も続きました。</li><li>日系企業を５社も訪問しました。</li></ul><p><strong>何度も：</strong> <strong>何度</strong> は疑問の表現ですが、<strong>何度も</strong> は**「何回も、たびたび」**という意味です。正確な回数は示さず、話し手はそれを多いものとして表します。</p><ul><li>あの映画は何度も見ましたよ。</li></ul><h2 id="でしょう-確認を求める-i" tabindex="-1">～でしょう（確認を求める I） <a class="header-anchor" href="#でしょう-確認を求める-i" aria-label="Permalink to &quot;～でしょう（確認を求める I）&quot;">​</a></h2><p><strong>規則：</strong> 名詞や形容詞の述語の後に <strong>でしょう</strong> を付け、<strong>上昇調</strong>で言うと、確認を求めたり、反語的に念を押したりする表現になります。くだけた話し言葉では <strong>でしょう</strong> はよく <strong>でしょ</strong> と縮まります。</p><ul><li>李さんも留学生でしょ？</li><li>勉強のほうが大事でしょう？</li><li>タバコを止めましょうよ。体に悪いでしょう？</li></ul><h2 id="n-のための-n-目的" tabindex="-1">N のための N（目的） <a class="header-anchor" href="#n-のための-n-目的" aria-label="Permalink to &quot;N のための N（目的）&quot;">​</a></h2><p><strong>規則：</strong> <strong>ため</strong> は目的を表します。目的を名詞で表すときは、その後に <strong>の</strong> を付けます：<strong>N のため</strong>。さらに名詞が続くときは、もう一つ <strong>の</strong> を加えてつなぎます：<strong>N₁ のための N₂</strong>（「N₁ に使う N₂」）。</p><ul><li>ここは小学生のための教室です。</li><li>海外旅行のためのタオルを買いました。</li><li>期末試験のための勉強計画を考えます。</li></ul><h2 id="の-ん-です-説明-ii-動詞" tabindex="-1">～の（／ん）です（説明 II：動詞） <a class="header-anchor" href="#の-ん-です-説明-ii-動詞" aria-label="Permalink to &quot;～の（／ん）です（説明 II：動詞）&quot;">​</a></h2><p><strong>接続：</strong> 動詞の普通形 ＋ <strong>の（／ん）です</strong>。話し言葉では <strong>んです</strong> のほうがよく使われます。</p><p><strong>規則：</strong> 上で名詞と形容詞について紹介した説明の文型 <strong>～の（／ん）です</strong> の動詞版です。疑問文では、聞き手に何かを<strong>説明</strong>してもらう表現になります。直前に言われたことや、話し手が気づいたり推測したりした状況について尋ねることが多いです。</p><ul><li>A：一緒に本屋へ行きませんか。</li><li>B：本屋へ何をしに行くんですか。</li><li>A：もう帰るんですか。</li><li>B：ええ、もう時間なので。</li><li>A：お腹が痛いんですか。</li><li>B：ええ、ちょっと。</li></ul><h2 id="v-ませんか-柔らかい勧誘" tabindex="-1">V ませんか（柔らかい勧誘） <a class="header-anchor" href="#v-ませんか-柔らかい勧誘" aria-label="Permalink to &quot;V ませんか（柔らかい勧誘）&quot;">​</a></h2><p><strong>規則：</strong> 丁寧な否定疑問の <strong>V ませんか</strong> を使って、<strong>一緒に</strong>何かをしようと誘います。<strong>V ましょうか</strong> より柔らかく聞こえ、<strong>いっしょに</strong> と一緒に使えます。</p><ul><li>来週のサークル活動にいっしょに参加しませんか。</li><li>明日、映画を見に行きませんか。</li><li>ここで写真を撮りませんか。</li></ul><h2 id="動詞の普通形-動詞の簡体形式" tabindex="-1">動詞の普通形（動詞の簡体形式） <a class="header-anchor" href="#動詞の普通形-動詞の簡体形式" aria-label="Permalink to &quot;動詞の普通形（動詞の簡体形式）&quot;">​</a></h2><p><strong>規則：</strong> 名詞や形容詞の述語と同じく、動詞の述語にも**丁寧形（敬体）<strong>と</strong>普通形（簡体）**があります。下の表は、時制と肯否の 4 つの組み合わせを比べたものです。<strong>Vる</strong> は動詞の辞書形を表しますが、辞書形の動詞がすべて <strong>る</strong> で終わるわけではありません。普通形の否定形と過去形は、後の文法項目で詳しく扱います。</p><table tabindex="0"><thead><tr><th>時制</th><th>肯否</th><th>丁寧形</th><th>普通形</th></tr></thead><tbody><tr><td>非過去（現在・未来）</td><td>肯定</td><td>V ます</td><td>V る（辞書形）</td></tr><tr><td>非過去（現在・未来）</td><td>否定</td><td>V ません</td><td>V ない</td></tr><tr><td>過去</td><td>肯定</td><td>V ました</td><td>V た</td></tr><tr><td>過去</td><td>否定</td><td>V ませんでした</td><td>V なかった</td></tr></tbody></table><p><strong>使い方：</strong> 丁寧形は改まった場面や丁寧な会話でよく使います。普通形は親しみのある響きで、友人や家族との会話でよく使います。書き言葉では、普通体は言い切りの調子になり、論文やニュース記事でよく使われます。</p><h2 id="v-る-辞書形" tabindex="-1">V る（辞書形） <a class="header-anchor" href="#v-る-辞書形" aria-label="Permalink to &quot;V る（辞書形）&quot;">​</a></h2><p><strong>規則：</strong> <strong>辞書形</strong>は動詞の基本の形で、辞書の見出しに使われる形です。また<strong>普通形の非過去・肯定</strong>の形でもあります。<strong>基本形</strong>や<strong>原形</strong>と呼ばれることもあります。下の組は、丁寧な <strong>ます</strong> 形と比べたものです。</p><table tabindex="0"><thead><tr><th>文体</th><th>例</th></tr></thead><tbody><tr><td>丁寧</td><td>スマホでウェブサイトを閲覧します。</td></tr><tr><td>普通</td><td>スマホでウェブサイトを閲覧する。</td></tr><tr><td>丁寧</td><td>よく徹夜します。</td></tr><tr><td>普通</td><td>よく徹夜する。</td></tr></tbody></table><h2 id="v-ない-普通形の否定形" tabindex="-1">V ない（普通形の否定形） <a class="header-anchor" href="#v-ない-普通形の否定形" aria-label="Permalink to &quot;V ない（普通形の否定形）&quot;">​</a></h2><p><strong>規則：</strong> 動詞の否定の語幹に否定の補助形容詞 <strong>ない</strong> を付けて、<strong>普通形の非過去・否定</strong>の形を作ります。語幹の作り方は動詞の種類によって異なります。</p><h3 id="i-類-五段動詞-1" tabindex="-1">I 類（五段動詞） <a class="header-anchor" href="#i-類-五段動詞-1" aria-label="Permalink to &quot;I 類（五段動詞）&quot;">​</a></h3><p>最後の仮名を <strong>ウ段</strong>から対応する <strong>ア段</strong>の仮名に変え、<strong>ない</strong> を付けます。<strong>う</strong> で終わる動詞は、<strong>ない</strong> の前で <strong>う</strong> を <strong>わ</strong> に変えます。</p><table tabindex="0"><thead><tr><th>辞書形</th><th>変化</th><th>普通形の否定</th></tr></thead><tbody><tr><td>使う</td><td>う → わ</td><td>使わない</td></tr><tr><td>歩く</td><td>く → か</td><td>歩かない</td></tr><tr><td>帰る</td><td>る → ら</td><td>帰らない</td></tr></tbody></table><h3 id="ii-類-一段動詞-1" tabindex="-1">II 類（一段動詞） <a class="header-anchor" href="#ii-類-一段動詞-1" aria-label="Permalink to &quot;II 類（一段動詞）&quot;">​</a></h3><p>最後の <strong>る</strong> を取り、<strong>ない</strong> を付けます。</p><table tabindex="0"><thead><tr><th>辞書形</th><th>普通形の否定</th></tr></thead><tbody><tr><td>見る</td><td>見ない</td></tr><tr><td>食べる</td><td>食べない</td></tr><tr><td>集める</td><td>集めない</td></tr></tbody></table><h3 id="iii-類-サ変・カ変-1" tabindex="-1">III 類（サ変・カ変） <a class="header-anchor" href="#iii-類-サ変・カ変-1" aria-label="Permalink to &quot;III 類（サ変・カ変）&quot;">​</a></h3><ul><li><strong>する：</strong> する → しない；利用する → 利用しない。</li><li><strong>来る（くる）：</strong> 来る → 来ない（こない）。</li></ul><p><strong>例外：</strong> <strong>ある</strong> の普通形の否定は <em>あらない</em> ではなく <strong>ない</strong> です。</p><ul><li>この週末は家に帰らない。</li><li>今の学生はあまり運動しない。</li></ul><h3 id="普通形の過去・否定-v-なかった" tabindex="-1">普通形の過去・否定：V なかった <a class="header-anchor" href="#普通形の過去・否定-v-なかった" aria-label="Permalink to &quot;普通形の過去・否定：V なかった&quot;">​</a></h3><p>普通形の過去・否定を作るには、<strong>V ない</strong> の最後の <strong>い</strong> を <strong>かった</strong> に変えます：<strong>V ない → V なかった</strong>。丁寧形の <strong>V ませんでした</strong> に対応します。</p><ul><li>宿題が多くて、昨夜、あまり寝なかった。</li><li>A：昨日のビールは？</li><li>B：冷蔵庫だよ。</li><li>A：ビールは冷蔵庫になかったよ。</li></ul><h2 id="動詞の連体形-動詞連体形" tabindex="-1">動詞の連体形（動詞連体形） <a class="header-anchor" href="#動詞の連体形-動詞連体形" aria-label="Permalink to &quot;動詞の連体形（動詞連体形）&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p><strong>規則：</strong> 動詞は<strong>名詞の直前</strong>に置いて、その名詞を説明したり特定したりできます。これを動詞の<strong>連体形</strong>といいます。形は動詞の普通形と同じで、意味に合わせて時制と肯否を選びます。たとえば <strong>行く場所</strong> は「（誰かが）行く場所」、<strong>飛ばない可能性</strong> は「（何かが）飛ばない可能性」という意味です。</p></div><ul><li>授業の予習や復習、課題をやる時間。</li><li>明日行く場所はどこですか。</li><li>雨なので、飛行機が飛ばない可能性があります。</li></ul><h2 id="n1-期間-に-n2-数量-v-頻度" tabindex="-1">N₁（期間）に N₂（数量）V（頻度） <a class="header-anchor" href="#n1-期間-に-n2-数量-v-頻度" aria-label="Permalink to &quot;N₁（期間）に N₂（数量）V（頻度）&quot;">​</a></h2><p><strong>規則：</strong> <strong>期間</strong>（多くは時間の幅）を表す名詞の後に <strong>に</strong> を付け、続けて<strong>回数</strong>を言うと、その期間内に動作がどのくらいの頻度で起こるかを表します。</p><ul><li>週に３回運動する。</li><li>２か月に１回ぐらい映画を観る。</li><li>１年に１回中国へ帰る。</li></ul><h2 id="n1-についての-n2-n1-についての-n2" tabindex="-1">N₁ についての N₂（N₁ についての N₂） <a class="header-anchor" href="#n1-についての-n2-n1-についての-n2" aria-label="Permalink to &quot;N₁ についての N₂（N₁ についての N₂）&quot;">​</a></h2><p><strong>規則：</strong> <strong>N について</strong> は話題を導く表現です。この句が後の名詞を修飾するときは <strong>の</strong> を付けます：<strong>N₁ についての N₂</strong>。</p><ul><li>こちらは大学生のライフスタイルについてのアンケートです。</li><li>このウェブサイトには、来週の口頭試験についての情報はない。</li><li>来週は期末試験なので、明日から経済学についての本を読む。</li></ul><h2 id="ほとんど-あまり-否定の動詞" tabindex="-1">ほとんど／あまり ＋ 否定の動詞 <a class="header-anchor" href="#ほとんど-あまり-否定の動詞" aria-label="Permalink to &quot;ほとんど／あまり ＋ 否定の動詞&quot;">​</a></h2><p><strong>規則：</strong> 副詞 <strong>ほとんど</strong> を否定の動詞と一緒に使うと、**「めったに……ない」「ほぼまったく……ない」<strong>という意味になります。<strong>あまり</strong> も否定の動詞と組み合わせて</strong>「それほど……ない」**という意味になります。否定の度合いは、一般に <strong>ほとんど</strong> のほうが <strong>あまり</strong> より強いです。</p><ul><li>インターネットやSNSはほとんど利用しません。</li><li>漫画はときどき読みますが、アニメはほとんど見ません。</li><li>Eメールはあまり使いません。</li><li>梅雨の季節はあまり晴れません。</li></ul><h2 id="n-助詞-の-n-名詞を修飾する" tabindex="-1">N ＋ 助詞 ＋ の ＋ N（名詞を修飾する） <a class="header-anchor" href="#n-助詞-の-n-名詞を修飾する" aria-label="Permalink to &quot;N ＋ 助詞 ＋ の ＋ N（名詞を修飾する）&quot;">​</a></h2><p><strong>規則：</strong> <strong>私の車</strong> のように 2 つの名詞を直接つなぐほかに、<strong>の</strong> は <strong>N と</strong>、<strong>N から</strong>、<strong>N で</strong>、<strong>N へ</strong> のような意味のある助詞句の後にも付きます。こうしてできた句が後の名詞を修飾します。</p><table tabindex="0"><thead><tr><th>動作の句</th><th>名詞句</th></tr></thead><tbody><tr><td>友達と食事する</td><td>友達との食事</td></tr><tr><td>明日からゴールデンウィークが始まる</td><td>明日からのゴールデンウィーク</td></tr><tr><td>デパートで買い物する</td><td>デパートでの買い物</td></tr><tr><td>大学の授業などに出席する</td><td>大学の授業などへの出席</td></tr></tbody></table><p><strong>メモ：</strong> <strong>N にの N</strong> という形はありません。目的地や方向に<strong>向かう</strong>意味のときは、代わりに <strong>N への N</strong> を使います。</p><ul><li>雨の影響で、外国からの観光客が減少しました。</li><li>後輩との食事会はとても楽しかったです。</li><li>台風の影響で、香港へのフライトはキャンセルになりました。</li></ul><h2 id="n1-や-n2-など-例を挙げる" tabindex="-1">N₁ や N₂ など（例を挙げる） <a class="header-anchor" href="#n1-や-n2-など-例を挙げる" aria-label="Permalink to &quot;N₁ や N₂ など（例を挙げる）&quot;">​</a></h2><p><strong>規則：</strong> <strong>や</strong> は、グループのすべてではなく、2 つ以上の<strong>例</strong>を挙げるときに使います。<strong>など</strong> は「その他にも」という意味です。2 つを合わせて <strong>N₁ や N₂ など</strong> としても、<strong>など</strong> を名詞の後に単独で付けてもかまいません。</p><ul><li>インターネットやSNSなど</li><li>A：デパートに何がありますか。</li><li>B：映画館や本屋などがあります。</li><li>A：いつもどこで服を買いますか。</li><li>B：ユニクロやタオバオで買います。</li></ul>',334)])])}const b=r(l,[["render",g]]);export{p as __pageData,b as default};
